function [Xdeltap_ipjp,Xdeltap_ipj,Xdeltap_ipjm,Xdeltap_imjp,Xdeltap_imj,Xdeltap_imjm,Xdeltam_ippjp,Xdeltam_ippjm,Xdeltam_ijp,Xdeltam_ijm,Xdeltam_immjp,Xdeltam_immjm] = weights_dke_jd(...Xdpnmm,Xdpnm,Xdpn,Xdpnp,Xdpnpp,...Xdmhumm,Xdmhum,Xdmhu,Xdmhup,Xdmhupp,...XDpp_ippj,XDpp_ipj,XDpp_ij,XDpp_imj,XDpp_immj,XDpm_ipj,XDpm_imj,XDmp_ijp,XDmp_ijm,XDmm_ijp,XDmm_ijm,...XFp_ippj,XFp_ipj,XFp_ij,XFp_imj,XFp_immj,XFm_ijp,XFm_ijm);%%Fokker-Planck engine for zero (usual FP code) or first order (neoclassical corrections for bootstrap current).%It calculates the matrix coefficients starting from diffusion and convection in momentum space. Full conservative%form. All processes are therefore considered in the same way%%	Input:%%%	Output:%%	- Xdeltap: Extended Chang & Cooper coefficients for momentum grid that are reused for fluxes calculations at the end of the code%	- Xdeltam: Extended Chang & Cooper coefficients for pitch-angle grid that are reused for fluxes calculations at the end of the code%	  (Notations: _imjp -> (i,j+1);_imjm -> (i,j);_ijp -> (i+1/2,j+1);_ijm -> (i+1/2,j);_immjp -> (i-1/2,j+1);_immjm -> (i-1/2,j)%%Last update:13/12/2002%%%By Joan Decker (MIT-RLE) and Yves Peysson (CEA-DRFC,yves.peysson@cea.fr) 13/12/2002%%Extended Chang & Cooper weights: link between full grid (flux mesh) and half grid (distribution mesh) in the momentum direction%Linear weighting in pitch-angle direction%	Xdeltap_ipjp = g_dke_yp(-Xdpnp.*XFp_ipj./XDpp_ipj,-(Xdpnpp - Xdpn).*(XFp_ippj./XDpp_ippj - XFp_ij./XDpp_ij)/4);		Xdeltap_ipj = g_dke_yp(-Xdpnp.*XFp_ipj./XDpp_ipj,-(Xdpnpp - Xdpn).*(XFp_ippj./XDpp_ippj - XFp_ij./XDpp_ij)/4);			Xdeltap_ipjm = g_dke_yp(-Xdpnp.*XFp_ipj./XDpp_ipj,-(Xdpnpp - Xdpn).*(XFp_ippj./XDpp_ippj - XFp_ij./XDpp_ij)/4);			Xdeltap_imjp = g_dke_yp(-Xdpnm.*XFp_imj./XDpp_imj,-(Xdpn - Xdpnmm).*(XFp_ij./XDpp_ij - XFp_immj./XDpp_immj)/4);	Xdeltap_imj = g_dke_yp(-Xdpnm.*XFp_imj./XDpp_imj,-(Xdpn - Xdpnmm).*(XFp_ij./XDpp_ij - XFp_immj./XDpp_immj)/4);	Xdeltap_imjm = g_dke_yp(-Xdpnm.*XFp_imj./XDpp_imj,-(Xdpn - Xdpnmm).*(XFp_ij./XDpp_ij - XFp_immj./XDpp_immj)/4);%	Xdeltam_ippjp = Xdmhupp./(Xdmhu + Xdmhupp);	Xdeltam_ijp = Xdmhupp./(Xdmhu + Xdmhupp);	Xdeltam_immjp = Xdmhupp./(Xdmhu + Xdmhupp);	Xdeltam_ippjm = Xdmhumm./(Xdmhu + Xdmhumm);	Xdeltam_ijm = Xdmhumm./(Xdmhu + Xdmhumm);	Xdeltam_immjm = Xdmhumm./(Xdmhu + Xdmhumm);